<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/functions.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT) ?: 0;
$p=proyecto_visible($pdo,$id);
if(!$p){http_response_code(404);encabezado('Proyecto no disponible');echo '<h1>Proyecto no encontrado</h1><a href="index.php">Volver a la galería</a>';pie();exit;}
$autores=autores_proyecto($pdo,$id);$medios=medios_proyecto($pdo,$id);
$q=$pdo->prepare('SELECT ROUND(AVG(puntuacion),1) promedio,COUNT(*) total FROM pro_valoraciones WHERE proyecto_id=?');$q->execute([$id]);$rating=$q->fetch();
encabezado($p['titulo']);
?><a class="volver" href="index.php">← Volver a proyectos</a><article class="detalle"><p class="eyebrow"><?=h($p['carrera'])?> · <?=h($p['tipo'])?> · <?=$p['anio']?></p><h1><?=h($p['titulo'])?></h1><p class="bajada"><?=h($p['resumen'])?></p><div class="texto"><?=nl2br(h($p['descripcion']))?></div><h2>Autores</h2><ul class="autores"><?php foreach($autores as $a):?><li><b><?=h($a['nombre'])?></b><?php if($a['contribucion']):?> · <?=h($a['contribucion'])?><?php endif;?></li><?php endforeach;?></ul><h2>Material del proyecto</h2><div class="medios"><?php foreach($medios as $m):?><a class="medio" href="descargar.php?id=<?=$m['id']?>"><?php if($m['tipo']==='imagen'):?><img src="descargar.php?id=<?=$m['id']?>" alt="<?=h($m['nombre_original'])?>"><?php else:?><span class="archivo"><?=h(strtoupper($m['tipo']))?></span><?php endif;?><span><?=h($m['nombre_original'])?></span></a><?php endforeach;?></div><p class="rating">Valoración promedio: <?=h((string)($rating['promedio']??'—'))?> / 5 (<?=$rating['total']?> valoraciones)</p><?php if(usuario_actual() && !es_curador()):?><form method="post" action="valorar.php" class="valorar"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="proyecto_id" value="<?=$id?>"><label>Tu valoración <select name="puntuacion"><option value="5">5 — Excelente</option><option value="4">4</option><option value="3">3</option><option value="2">2</option><option value="1">1 — Necesita mejorar</option></select></label><button class="boton">Valorar</button></form><?php else:?><p><a href="admin/login.php">Inicia sesión como aspirante</a> para valorar este proyecto.</p><?php endif;?></article><?php pie(); ?>
